#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto doOp = [&](int x, int y){
        assert(x>0 && y>0 && x+y<n);
        ops.push_back({x,y});
        vector<int> np(n);
        for(int i=0;i<y;i++) np[i]=p[n-y+i];
        for(int i=y;i<n-x;i++) np[i]=p[x+i-y];
        for(int i=n-x;i<n;i++) np[i]=p[i-(n-x)];
        p=np;
    };

    for(int placed=0; placed<n;placed++){
        int pos=-1;
        for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        if(pos==placed) continue;
        if(n<=2) break; // can't do ops if n<=2 since x+y<n and x,y>=1 requires n>=3

        // Move element from pos to position 0 first, then from 0 to placed
        // Step 1: move to position 0 using y=n-pos (element at pos is start of suffix)
        if(pos>0 && pos<n-1){
            int y=n-pos, x=1;
            if(x+y<n) doOp(x,y); 
            else { x=1; y=n-pos; /* x+y=n-pos+1, need <n => pos>1 */ if(x+y>=n){doOp(pos,1);pos=n-1; doOp(1,1);} else doOp(x,y);}
            pos=0;
        } else if(pos==n-1){
            doOp(1,1); // brings last to front
            pos=0;
        }
        // Now element is at position 0, move to placed
        if(placed==0) continue;
        // op(placed, 1): suffix[n-1]→0, middle[placed..n-2]→[1..n-placed-1], prefix[0..placed-1]→[n-placed..n-1]
        // Element at 0 goes to n-placed. Not right.
        // op(1, n-1-placed): element at 0 goes to prefix→position n-1. Then suffix=[placed+1..n-1] goes to [0..n-2-placed], middle=[1..placed] to [n-1-placed..n-2], prefix=[0] to [n-1].
        // Hmm. op(1, n-1-placed): element at 0 → position n-1. positions[1..placed]→[n-1-placed..n-2]. Not helpful directly.
        // Actually use op with x=1,y=n-placed-1 to put element at end, then op(placed+1,1) to cycle.
        if(placed+2<=n){
            doOp(1,n-placed-1);
            doOp(placed+1,1);
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
